#!/bin/bash
# smoke test: 20 programs x 2 conditions per model; every model must load and print plausible predictions
mkdir -p rank_out
echo "== StarCoder2-15B"; CUDA_VISIBLE_DEVICES=1 python3 cafa_revision.py rerun --gguf "models/starcoder2-15b-Q4_K_M.gguf" --conditions 1,2 --demo orig --limit 20 --out rank_out/smoke_StarCoder2_15B.jsonl 2>&1 | tail -n 2; python3 -c "import json;r=[json.loads(l) for l in open('rank_out/smoke_StarCoder2_15B.jsonl')];ok=[x for x in r if x.get('status')=='ok'];print(len(ok),'scored of',len(r),'| first predictions:',[x['prediction'][:25] for x in ok[:3]])"
